  1→import express, { Request, Response } from "express";
  2→import { query, AgentDefinition, SettingSource, HookCallbackMatcher } from "@anthropic-ai/claude-agent-sdk";
  3→import { Langfuse } from "langfuse";
  4→import { mkdirSync, writeFileSync, existsSync, readdirSync, readFileSync } from "fs";
  5→import { homedir } from "os";
  6→import { join } from "path";
  7→import type { QueryRequest, HealthResponse, AgentDefinitionPayload } from "./types.js";
  8→
  9→// Claude CLI requires certain directories/files under ~/.claude to exist.
 10→// The container uses a tmpfs mount at ~/.claude which starts empty, so we
 11→// create the expected structure at startup.
 12→const claudeDir = join(homedir(), ".claude");
 13→for (const sub of ["debug", "projects"]) {
 14→  const dir = join(claudeDir, sub);
 15→  if (!existsSync(dir)) {
 16→    mkdirSync(dir, { recursive: true });
 17→  }
 18→}
 19→const settingsFile = join(claudeDir, "remote-settings.json");
 20→if (!existsSync(settingsFile)) {
 21→  writeFileSync(settingsFile, "{}");
 22→}
 23→
 24→// Skills are bind-mounted at the project-level path (/app/.claude/skills/)
 25→// so the CLI subprocess (spawned by the SDK with cwd=/app/) discovers them.
 26→const SKILLS_DIR = join(process.cwd(), ".claude", "skills");
 27→
 28→function isSkillDisabled(skillPath: string): boolean {
 29→  try {
 30→    const text = readFileSync(skillPath, "utf-8");
 31→    if (!text.startsWith("---")) return false;
 32→    const end = text.indexOf("---", 3);
 33→    if (end === -1) return false;
 34→    const frontmatter = text.slice(3, end);
 35→    for (const line of frontmatter.split("\n")) {
 36→      if (line.trim().startsWith("disabled:") && line.trim().endsWith("true")) {
 37→        return true;
 38→      }
 39→    }
 40→  } catch {
 41→    // ignore read errors
 42→  }
 43→  return false;
 44→}
 45→
 46→function discoverSkills(): Set<string> {
 47→  if (!existsSync(SKILLS_DIR)) return new Set();
 48→  return new Set(
 49→    readdirSync(SKILLS_DIR, { withFileTypes: true })
 50→      .filter((d) => {
 51→        if (!d.isDirectory()) return false;
 52→        const skillPath = join(SKILLS_DIR, d.name, "SKILL.md");
 53→        return existsSync(skillPath) && !isSkillDisabled(skillPath);
 54→      })
 55→      .map((d) => d.name)
 56→  );
 57→}
 58→
 59→// Log initial skills at startup
 60→console.log(`[sidecar] Initial skills: ${[...discoverSkills()].join(", ") || "(none)"}`);
 61→
 62→const skillAllowlistHook: HookCallbackMatcher = {
 63→  matcher: "Skill",
 64→  hooks: [
 65→    async (input) => {
 66→      const currentSkills = discoverSkills();
 67→      const toolInput = (input as Record<string, unknown>).tool_input as Record<string, unknown> | undefined;
 68→      const skillName = toolInput?.skill as string | undefined;
 69→      if (skillName && !currentSkills.has(skillName)) {
 70→        return {
 71→          hookSpecificOutput: {
 72→            hookEventName: "PreToolUse" as const,
 73→            permissionDecision: "deny" as const,
 74→            permissionDecisionReason: `Skill "${skillName}" is not in the allowlist.`,
 75→          },
 76→        };
 77→      }
 78→      return {};
 79→    },
 80→  ],
 81→};
 82→
 83→// Initialize Langfuse if credentials are available (reads from env vars
 84→// LANGFUSE_PUBLIC_KEY, LANGFUSE_SECRET_KEY, LANGFUSE_BASE_URL automatically)
 85→let langfuse: Langfuse | null = null;
 86→if (process.env.LANGFUSE_PUBLIC_KEY && process.env.LANGFUSE_SECRET_KEY) {
 87→  langfuse = new Langfuse();
 88→  console.log("[sidecar] Langfuse tracing enabled");
 89→}
 90→
 91→const app = express();
 92→app.use(express.json({ limit: "10mb" }));
 93→
 94→const PORT = parseInt(process.env.PORT || "3000", 10);
 95→
 96→// Per-request abort tracking — avoids a global variable whose cleanup in one
 97→// request's `finally` block can clobber a concurrently-started request.
 98→let nextRequestId = 0;
 99→const activeAborts = new Map<number, AbortController>();
100→
101→// How long (ms) to wait for the SDK iterator to yield a message before
102→// aborting.  Resets on every message so active multi-turn queries are not
103→// interrupted.  Covers cases where the CLI subprocess hangs on startup
104→// (e.g. broken session resume, unreachable MCP server).
105→const SDK_IDLE_TIMEOUT_MS = parseInt(process.env.SDK_IDLE_TIMEOUT_MS || "120000", 10);
106→
107→// Timeout (ms) for pre-flight reachability checks against MCP / API URLs.
108→const PREFLIGHT_TIMEOUT_MS = 10_000; // 10 seconds
109→
110→app.get("/health", (_req: Request, res: Response) => {
111→  const response: HealthResponse = { status: "ok" };
112→  res.json(response);
113→});
114→
115→app.post("/query", async (req: Request, res: Response) => {
116→  const body = req.body as QueryRequest;
117→
118→  if (!body.message || !body.system_prompt) {
119→    res.status(400).json({ error: "message and system_prompt are required" });
120→    return;
121→  }
122→
123→  // Set up SSE headers
124→  res.setHeader("Content-Type", "text/event-stream");
125→  res.setHeader("Cache-Control", "no-cache");
126→  res.setHeader("Connection", "keep-alive");
127→  res.setHeader("X-Accel-Buffering", "no");
128→  res.flushHeaders();
129→
130→  const abortController = new AbortController();
131→  const requestId = nextRequestId++;
132→  activeAborts.set(requestId, abortController);
133→
134→  // Merge per-request env overrides (e.g. Bifrost gateway URLs) with process env
135→  const sdkEnv: Record<string, string> = {};
136→  for (const [k, v] of Object.entries(process.env)) {
137→    if (v !== undefined) sdkEnv[k] = v;
138→  }
139→  if (body.env) {
140→    Object.assign(sdkEnv, body.env);
141→  }
142→  // Scrub Langfuse credentials so the agent subprocess cannot read them from
143→  // the inherited environment — matches backend subprocess behaviour.
144→  // The sidecar's own Langfuse client already holds the credentials internally.
145→  sdkEnv["LANGFUSE_PUBLIC_KEY"] = "";
146→  sdkEnv["LANGFUSE_SECRET_KEY"] = "";
147→
148→  let responseEnded = false;
149→
150→  // Detect client disconnect
151→  res.on("close", () => {
152→    if (!responseEnded) {
153→      abortController.abort();
154→    }
155→  });
156→
157→  // --- Langfuse tracing setup ---
158→  // Mirror the backend's session ID handling:
159→  //   - langfuse_session_id (from frontend for edit/delete) takes priority
160→  //   - session_id (CLI session from previous turn) as fallback
161→  const modelName = body.model || process.env.ORCHESTRATOR_MODEL || "claude-sonnet-4-6";
162→  const traceMessage = body.original_message || body.message;
163→  const traceInput: Record<string, unknown> = {
164→    message: traceMessage.substring(0, 500),
165→  };
166→  if (body.conversation_history && body.conversation_history.length > 0) {
167→    traceInput.conversation_history = body.conversation_history;
168→  }
169→  const trace = langfuse?.trace({
170→    name: "agent-chat",
171→    sessionId: body.langfuse_session_id || body.session_id || undefined,
172→    input: traceInput,
173→    metadata: { model: modelName, mode: "container" },
174→  });
175→
176→  // Per-turn usage tracking from stream events
177→  let currentGenUsage: { input?: number; output?: number } = {};
178→  // Accumulated messages for generation input context
179→  const accumulatedMessages: Array<{ role: string; content: unknown }> = [
180→    { role: "user", content: body.message },
181→  ];
182→
183→  // Collect stderr from the CLI subprocess for debugging
184→  const stderrLines: string[] = [];
185→
186→  // Declared here so `finally` can clear it even if `try` throws early
187→  let idleTimer: ReturnType<typeof setTimeout> | null = null;
188→
189→  try {
190→    // --- Pre-flight reachability checks ---
191→    // The CLI subprocess will hang silently if it can't reach the MCP SSE
192→    // server or the Bifrost LLM gateway.  Test connectivity first so we can
193→    // fail fast with a useful error message.
194→    const apiBase = sdkEnv["ANTHROPIC_BASE_URL"] || "";
195→    console.log(
196→      `[sidecar] reqId=${requestId} mcp_url=${body.mcp_server_url || "(none)"} api_base=${apiBase} session_id=${body.session_id || "(none)"}`
197→    );
198→
199→    if (body.mcp_server_url) {
200→      try {
201→        const mcpResp = await fetch(body.mcp_server_url, {
202→          signal: AbortSignal.timeout(PREFLIGHT_TIMEOUT_MS),
203→        });
204→        // SSE endpoints normally return 200 with text/event-stream; any
205→        // non-error status is fine — we just need to know the host is up.
206→        mcpResp.body?.cancel(); // don't consume the stream
207→        console.log(`[sidecar] MCP reachability OK (status=${mcpResp.status})`);
208→      } catch (e: unknown) {
209→        const reason = e instanceof Error ? e.message : String(e);
210→        throw new Error(
211→          `MCP server unreachable at ${body.mcp_server_url}: ${reason}. ` +
212→          `Check that BACKEND_BASE_URL is reachable from inside the container.`
213→        );
214→      }
215→    }
216→
217→    if (apiBase) {
218→      try {
219→        // Just a quick TCP-level check — Bifrost will return 4xx without
220→        // a real API key but that still proves reachability.
221→        const apiResp = await fetch(`${apiBase}/v1/models`, {
222→          signal: AbortSignal.timeout(PREFLIGHT_TIMEOUT_MS),
223→        });
224→        apiResp.body?.cancel();
225→        console.log(`[sidecar] Bifrost LLM gateway reachability OK (status=${apiResp.status})`);
226→      } catch (e: unknown) {
227→        const reason = e instanceof Error ? e.message : String(e);
228→        throw new Error(
229→          `Bifrost LLM gateway unreachable at ${apiBase}: ${reason}. ` +
230→          `Check that BIFROST_BASE_URL is reachable from inside the container.`
231→        );
232→      }
233→    }
234→
235→    // Convert agents payload from the backend into SDK AgentDefinition objects.
236→    // The SDK only accepts 'sonnet' | 'opus' | 'haiku' | 'inherit' for model.
237→    // Arbitrary strings (e.g. "openai/gpt-5.2") are silently rejected, causing
238→    // the agent to not be registered.  Validate and fall back to "inherit".
239→    const VALID_AGENT_MODELS = new Set(["sonnet", "opus", "haiku", "inherit"]);
240→    let sdkAgents: Record<string, AgentDefinition> | undefined;
241→    if (body.agents) {
242→      sdkAgents = {};
243→      for (const [name, def] of Object.entries(body.agents)) {
244→        const model = def.model && VALID_AGENT_MODELS.has(def.model)
245→          ? (def.model as AgentDefinition["model"])
246→          : "inherit";
247→        sdkAgents[name] = {
248→          description: def.description,
249→          prompt: def.prompt,
250→          ...(def.tools ? { tools: def.tools } : {}),
251→          model,
252→        };
253→      }
254→    }
255→
256→    // Append skill restriction so the model doesn't list or suggest
257→    // built-in skills that the PreToolUse hook would block anyway.
258→    // The CLI binary injects its own system reminder listing ALL skills
259→    // (including built-ins like "simplify"), so we must explicitly tell
260→    // the model to ignore any skills not in our allowlist.
261→    const currentSkills = discoverSkills();
262→    const allowedList = [...currentSkills].join(", ");
263→    const skillRestriction = currentSkills.size > 0
264→      ? `\n\nCRITICAL SKILL RESTRICTION: Your ONLY available skills are: ${allowedList}. You may see other skills (like "simplify") listed in system reminders — those are NOT available to you and MUST be ignored. When asked about available skills, list ONLY: ${allowedList}. Never mention, suggest, or attempt to invoke any skill not in this list.`
265→      : "\n\nCRITICAL SKILL RESTRICTION: You have NO skills available. You may see skills listed in system reminders — those are NOT available to you and MUST be ignored. Never mention, suggest, or attempt to invoke any skills.";
266→
267→    const skillInstruction = body.skills?.length
268→      ? `\n\nIMPORTANT: The user has invoked the following skill(s): ${body.skills.map(s => `"/${s}"`).join(", ")}. You MUST use the Skill tool to invoke each skill (${body.skills.map(s => `"${s}"`).join(", ")}) before doing anything else.`
269→      : "";
270→
271→    // Common SDK options (without resume/prompt — those vary on retry)
272→    const baseOptions = {
273→      model: modelName,
274→      systemPrompt: body.system_prompt + skillInstruction + skillRestriction,
275→      allowedTools: ["Skill", "Task", "mcp__duckdb-data-agent__execute_sql", "mcp__duckdb-data-agent__ask_user_question", "mcp__duckdb-data-agent__render_chart", "mcp__duckdb-data-agent__create_skill"] as string[],
276→      settingSources: ["project"] as SettingSource[],
277→      plugins: [],
278→      hooks: { PreToolUse: [skillAllowlistHook] },
279→      permissionMode: "bypassPermissions" as const,
280→      allowDangerouslySkipPermissions: true,
281→      maxTurns: 20,
282→      includePartialMessages: true,
283→      abortController,
284→      env: sdkEnv,
285→      stderr: (line: string) => {
286→        stderrLines.push(line);
287→        console.error(`[sidecar:cli] ${line}`);
288→      },
289→      ...(sdkAgents ? { agents: sdkAgents } : {}),
290→      ...(body.mcp_server_url
291→        ? {
292→            mcpServers: {
293→              "duckdb-data-agent": {
294→                type: "sse" as const,
295→                url: body.mcp_server_url,
296→              },
297→            },
298→          }
299→        : {}),
300→    };
301→
302→    // Resume fallback: try with resume first. If the SDK yields a "result"
303→    // message with "No conversation found" (container was recreated and lost
304→    // the session), suppress that error and retry without resume, prepending
305→    // conversation history so the model has context.
306→    //
307→    // When resuming, the SDK reuses the original session's system prompt, so
308→    // skill changes (additions/deletions) since conversation start won't be
309→    // reflected.  Prepend an updated skill restriction to the user message so
310→    // the model always sees the current set of available skills.
311→    let useResume = !!body.session_id;
312→    let currentPrompt = useResume
313→      ? `${skillRestriction}\n\n${body.message}`
314→      : body.message;
315→    let retried = false;
316→
317→    queryLoop: for (let attempt = 0; attempt < 2; attempt++) {
318→      const sdkQuery = query({
319→        prompt: currentPrompt,
320→        options: {
321→          ...baseOptions,
322→          ...(useResume ? { resume: body.session_id } : {}),
323→        },
324→      });
325→
326→      console.log(
327→        `[sidecar] SDK query started model=${modelName} reqId=${requestId} attempt=${attempt} resume=${useResume}`
328→      );
329→
330→      idleTimer = setTimeout(() => {
331→        console.error(`[sidecar] SDK idle timeout (${SDK_IDLE_TIMEOUT_MS}ms) reached, aborting reqId=${requestId}`);
332→        abortController.abort();
333→      }, SDK_IDLE_TIMEOUT_MS);
334→
335→      let resumeFailedNeedsRetry = false;
336→
337→      try {
338→        for await (const message of sdkQuery) {
339→          // Reset idle timer on every message
340→          if (idleTimer) { clearTimeout(idleTimer); }
341→          idleTimer = setTimeout(() => {
342→            console.error(`[sidecar] SDK idle timeout (${SDK_IDLE_TIMEOUT_MS}ms) reached, aborting reqId=${requestId}`);
343→            abortController.abort();
344→          }, SDK_IDLE_TIMEOUT_MS);
345→
346→          if (responseEnded) break queryLoop;
347→
348→          // Intercept "No conversation found" result before forwarding
349→          if (useResume && !retried) {
350→            const msg = message as Record<string, unknown>;
351→            if (msg.type === "result" && msg.is_error) {
352→              const resultText = String(msg.result || "");
353→              const errors = ((msg.errors as string[]) || []).join(" ");
354→              if ((resultText + " " + errors).includes("No conversation found")
355→                  && body.conversation_history && body.conversation_history.length > 0) {
356→                console.log(`[sidecar] Resume failed ("No conversation found"), will retry with history reqId=${requestId}`);
357→                resumeFailedNeedsRetry = true;
358→                break; // Don't forward this error to the client
359→              }
360→            }
361→          }
362→
363→          // Forward each SDK message as an SSE data line
364→          res.write(`data: ${JSON.stringify(message)}\n\n`);
365→
366→          // --- Create Langfuse observations from SDK messages ---
367→          if (!trace) continue;
368→          const msg = message as Record<string, unknown>;
369→
370→          if (msg.type === "stream_event") {
371→            const event = (msg.event as Record<string, unknown>) || {};
372→            const eventType = event.type as string;
373→            if (eventType === "message_start") {
374→              const msgData = (event.message as Record<string, unknown>) || {};
375→              const usage = (msgData.usage as Record<string, number>) || {};
376→              currentGenUsage = { input: usage.input_tokens || 0 };
377→            } else if (eventType === "message_delta") {
378→              const usage = (event.usage as Record<string, number>) || {};
379→              currentGenUsage.output = usage.output_tokens || 0;
380→            }
381→          } else if (msg.type === "assistant") {
382→            const msgObj = (msg.message as Record<string, unknown>) || {};
383→            const content = msgObj.content as unknown[];
384→            const usage =
385→              currentGenUsage.input !== undefined
386→                ? {
387→                    input: currentGenUsage.input || 0,
388→                    output: currentGenUsage.output || 0,
389→                    total: (currentGenUsage.input || 0) + (currentGenUsage.output || 0),
390→                    unit: "TOKENS" as const,
391→                  }
392→                : undefined;
393→            const gen = trace.generation({
394→              name: "claude.assistant.turn",
395→              model: (msgObj.model as string) || modelName,
396→              input: { messages: accumulatedMessages.slice(-6) },
397→              output: { content, role: "assistant" },
398→              usage,
399→            });
400→            gen.end();
401→            currentGenUsage = {};
402→            accumulatedMessages.push({ role: "assistant", content });
403→          } else if (msg.type === "user") {
404→            const msgObj = (msg.message as Record<string, unknown>) || {};
405→            accumulatedMessages.push({ role: "user", content: msgObj.content });
406→          } else if (msg.type === "result") {
407→            const actualSessionId = (msg.session_id as string | undefined) || body.session_id;
408→            const traceSessionId = body.langfuse_session_id || actualSessionId;
409→            trace.update({
410→              ...(traceSessionId ? { sessionId: traceSessionId } : {}),
411→              output: { session_id: actualSessionId },
412→            });
413→          } else if (msg.type === "system") {
414→            const sessionId = msg.session_id as string | undefined;
415→            if (sessionId && !body.langfuse_session_id) {
416→              trace.update({ sessionId });
417→            }
418→          }
419→        } // end for-await
420→      } catch (innerErr: unknown) {
421→        // If we're retrying due to resume failure, swallow the cleanup error
422→        // (e.g., "Claude Code process exited with code 1" after session not found)
423→        if (resumeFailedNeedsRetry) {
424→          console.log(`[sidecar] Swallowing post-resume error during retry: ${innerErr instanceof Error ? innerErr.message : String(innerErr)}`);
425→        } else {
426→          throw innerErr;
427→        }
428→      }
429→
430→      if (resumeFailedNeedsRetry && !retried) {
431→        retried = true;
432→        useResume = false;
433→        let messageWithHistory = "Previous conversation (for context):\n";
434→        for (const entry of body.conversation_history!) {
435→          const role = (entry.role || "user").charAt(0).toUpperCase() + (entry.role || "user").slice(1);
436→          messageWithHistory += `\n${role}: ${entry.content}\n`;
437→        }
438→        messageWithHistory += `\n---\n\nMy new message:\n${body.message}`;
439→        currentPrompt = messageWithHistory;
440→        stderrLines.length = 0;
441→        if (idleTimer) { clearTimeout(idleTimer); idleTimer = null; }
442→        continue; // retry the queryLoop
443→      }
444→
445→      break; // success or non-retryable error — exit queryLoop
446→    } // end queryLoop
447→  } catch (err: unknown) {
448→    let errMsg = err instanceof Error ? err.message : String(err);
449→    // Append CLI stderr for context when the process crashes
450→    if (stderrLines.length > 0) {
451→      errMsg += ` | CLI stderr: ${stderrLines.slice(-5).join(" ")}`;
452→    }
453→    // Don't log abort errors — they are expected on client disconnect
454→    if (!(err instanceof Error && err.name === "AbortError")) {
455→      console.error(`[sidecar] SDK error: ${errMsg}`);
456→      if (!responseEnded) {
457→        res.write(
458→          `data: ${JSON.stringify({ type: "error", message: errMsg })}\n\n`
459→        );
460→      }
461→      if (trace) {
462→        trace.update({ output: { error: errMsg } });
463→      }
464→    }
465→  } finally {
466→    if (idleTimer) { clearTimeout(idleTimer); }
467→    activeAborts.delete(requestId);
468→    responseEnded = true;
469→    res.end();
470→    // Flush Langfuse events before the response is fully closed
471→    if (langfuse) {
472→      await langfuse.flushAsync().catch(() => {});
473→    }
474→    console.log(`[sidecar] SSE stream ended reqId=${requestId}`);
475→  }
476→});
477→
478→app.post("/stop", (_req: Request, res: Response) => {
479→  if (activeAborts.size > 0) {
480→    for (const [id, controller] of activeAborts) {
481→      controller.abort();
482→      activeAborts.delete(id);
483→    }
484→    res.json({ status: "stopped" });
485→  } else {
486→    res.json({ status: "no_active_session" });
487→  }
488→});
489→
490→app.listen(PORT, "0.0.0.0", () => {
491→  console.log(`Sidecar agent server listening on port ${PORT}`);
492→});
493→

 1→import type { SkillInfo } from '../types';
 2→
 3→export async function fetchSkills(): Promise<SkillInfo[]> {
 4→  const resp = await fetch('/api/skills');
 5→  if (!resp.ok) throw new Error('Failed to fetch skills');
 6→  return resp.json();
 7→}
 8→
 9→export async function fetchSkill(name: string): Promise<SkillInfo> {
10→  const resp = await fetch(`/api/skills/${encodeURIComponent(name)}`);
11→  if (!resp.ok) throw new Error(`Skill '${name}' not found`);
12→  return resp.json();
13→}
14→
15→export async function createSkill(skill: SkillInfo): Promise<SkillInfo> {
16→  const resp = await fetch('/api/skills', {
17→    method: 'POST',
18→    headers: { 'Content-Type': 'application/json' },
19→    body: JSON.stringify(skill),
20→  });
21→  if (!resp.ok) {
22→    const err = await resp.json();
23→    throw new Error(err.error || 'Failed to create skill');
24→  }
25→  return resp.json();
26→}
27→
28→export async function deleteSkill(name: string): Promise<void> {
29→  const resp = await fetch(`/api/skills/${encodeURIComponent(name)}`, { method: 'DELETE' });
30→  if (!resp.ok) {
31→    const err = await resp.json();
32→    throw new Error(err.error || 'Failed to delete skill');
33→  }
34→}
35→
36→export async function toggleSkill(name: string, disabled: boolean): Promise<SkillInfo> {
37→  const resp = await fetch(`/api/skills/${encodeURIComponent(name)}/toggle`, {
38→    method: 'PATCH',
39→    headers: { 'Content-Type': 'application/json' },
40→    body: JSON.stringify({ disabled }),
41→  });
42→  if (!resp.ok) {
43→    const err = await resp.json();
44→    throw new Error(err.error || 'Failed to toggle skill');
45→  }
46→  return resp.json();
47→}
